import { tags } from "typia";

/**
 * Common time range structure used by analytics request and response DTOs for
 * the ShoppingMall platform.
 *
 * Represents either an explicit closed interval between start and end
 * timestamps or a normalized interval derived from a preset (such as
 * last_24_hours). All timestamps are expressed in ISO 8601 date-time format in
 * UTC.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallAnalyticsTimeRange = {
  /**
   * Inclusive start timestamp of the analytics window in ISO 8601 date-time
   * format (UTC).
   */
  start: string & tags.Format<"date-time">;

  /**
   * Exclusive end timestamp of the analytics window in ISO 8601 date-time
   * format (UTC).
   *
   * Implementations should ensure that end is strictly later than start.
   */
  end: string & tags.Format<"date-time">;
};
